class Heap {
  private items: number[] = []
  constructor(private before: (a: number, b: number) => boolean) {}
  get size() {
    return this.items.length
  }
  peek() {
    return this.items[0]
  }
  push(v: number) {
    const a = this.items
    a.push(v)
    let i = a.length - 1
    while (i > 0) {
      const p = (i - 1) >> 1
      if (!this.before(a[i], a[p])) break
      ;[a[i], a[p]] = [a[p], a[i]]
      i = p
    }
  }
  pop(): number {
    const a = this.items
    const top = a[0]
    const last = a.pop()!
    if (a.length) {
      a[0] = last
      let i = 0
      for (;;) {
        const l = 2 * i + 1
        const r = l + 1
        let m = i
        if (l < a.length && this.before(a[l], a[m])) m = l
        if (r < a.length && this.before(a[r], a[m])) m = r
        if (m === i) break
        ;[a[i], a[m]] = [a[m], a[i]]
        i = m
      }
    }
    return top
  }
}

class MedianFinder {
  private low = new Heap((a, b) => a > b)
  private high = new Heap((a, b) => a < b)

  addNum(num: number): void {
    this.low.push(num)
    this.high.push(this.low.pop())
    if (this.high.size > this.low.size) this.low.push(this.high.pop())
  }

  findMedian(): number {
    return this.low.size > this.high.size ? this.low.peek() : (this.low.peek() + this.high.peek()) / 2
  }
}
